#include <stdio.h>

int biggest(int fish[], int count) {
    int best = fish[0];
    for (int i = 1; i < count; i++) {
        if (fish[i] > best) {
            best = fish[i];
        }
    }
    return best;
}

int main(void) {
    int fish[3] = {6, 8, 3};
    printf("三碗：%d\n", biggest(fish, 3));
    printf("一碗都没有：%d\n", biggest(fish, 0));
    return 0;
}

#include <stdio.h>

int main(void) {
    int fish[3] = {5, 3, 4};
    int total = 0;
    for (int i = 0; i < 3; i++) {
        total += fish[i];
        printf("第 %d 碗：%d 条\n", i + 1, fish[i]);
    }
    printf("合计：%d 条\n", total);
    return 0;
}
